import json, re, glob

def placeholders(s):
    return set(re.findall(r'\{[^}]*\}', s))

for f in sorted(glob.glob('*.fr.json')) + sorted(glob.glob('*.es.json')):
    with open(f) as fh:
        data = json.load(fh)
    for k, v in data.items():
        pk = placeholders(k)
        pv = placeholders(v)
        if pk != pv:
            print(f, '|', k, '->', v, '| missing/extra:', pk ^ pv)
        # check for stray HTML tags
        tagk = re.findall(r'<[^>]+>', k)
        tagv = re.findall(r'<[^>]+>', v)
        if tagk != tagv:
            print("HTML mismatch", f, k, '->', v)
