import json, glob, re

nbsp = ' '
nnbsp = ' '
for f in sorted(glob.glob('*.fr.json')):
    with open(f, encoding='utf-8') as fh:
        data = json.load(fh)
    for k, v in data.items():
        for m in re.finditer(r'(.)?[:;!?]', v):
            # check preceding char before punctuation mark, for real colon/semicolon/!/? (not part of URL, time, etc.)
            idx = m.start()
            punct = v[idx] if v[idx] in ':;!?' else None
        # simpler: find all occurrences of ' :' vs nbsp+':' etc
        for punct in [':', ';', '!', '?']:
            for pos in range(len(v)):
                if v[pos] == punct:
                    prev = v[pos-1] if pos > 0 else ''
                    if prev == ' ':
                        print(f"REGULAR SPACE before '{punct}' in {f}: {k!r} -> {v!r}")
